import { useEffect } from "react";
import { useLocation } from "react-router-dom";
import { api } from "@/lib/api";

const REF_KEY = "lumo_ref_code";
const REF_TS_KEY = "lumo_ref_code_ts";
const REF_TTL_MS = 30 * 24 * 60 * 60 * 1000; // 30 days

/**
 * `?ref=<code>` capture.
 *
 * Any inbound URL carrying `?ref=XXXX` (typically a share link generated by
 * /api/referrals/me → `share_url`) writes the code to localStorage. When
 * the user later signs up, `AuthProvider.register()` attaches it to the
 * `/api/auth/register` payload and the backend stamps the new user with
 * `referred_by_user_id`.
 *
 * Design notes:
 *   - We stamp a timestamp alongside the code so the reward can expire
 *     after 30 days — prevents someone hoarding an old link for a year
 *     and re-attributing every future signup.
 *   - Only the FIRST touch wins (`localStorage.setItem` only if empty)
 *     so a referred user who later visits a bare / URL keeps their
 *     original referrer credit.
 *   - Ref codes are canonicalized to uppercase — matches backend's
 *     lookup, which does the same before querying `referral_code`.
 */
const ATTR_KEY = "lumo_attr";

// First-touch UTM capture (30 days) + one click event per post per session.
function captureUtm(search) {
  try {
    const p = new URLSearchParams(search || "");
    const src = p.get("utm_source");
    if (!src) return;
    const attr = {
      utm_source: src, utm_medium: p.get("utm_medium") || undefined,
      utm_campaign: p.get("utm_campaign") || undefined, utm_content: p.get("utm_content") || undefined,
      landing_path: window.location.pathname, ts: Date.now(),
    };
    const prev = JSON.parse(localStorage.getItem(ATTR_KEY) || "null");
    if (!prev || Date.now() - (prev.ts || 0) > REF_TTL_MS) localStorage.setItem(ATTR_KEY, JSON.stringify(attr));
    const seenKey = `lumo_click_${src}_${attr.utm_content || ""}`;
    if (sessionStorage.getItem(seenKey)) return;
    sessionStorage.setItem(seenKey, "1");
    api.post("/attribution/click", { ...attr, ts: undefined, landing_path: undefined, path: attr.landing_path }).catch(() => {});
  } catch { /* storage disabled */ }
}

export function readAttribution() {
  try {
    const a = JSON.parse(localStorage.getItem(ATTR_KEY) || "null");
    if (!a || Date.now() - (a.ts || 0) > REF_TTL_MS) return null;
    const { ts, ...rest } = a;
    return rest;
  } catch { return null; }
}

// Extra fields for Google / SMS sign-in so new accounts are still credited to their recruiter.
export function signupExtras(next = "") {
  let ref = null;
  try { ref = localStorage.getItem("lumo_ref_code") || null; } catch { /* private mode */ }
  const attr = readAttribution();
  const city = new URLSearchParams((next.split("?")[1]) || "").get("recruit_city_slug");
  return { ...(ref ? { ref_code: ref } : {}), ...(attr ? { signup_source: attr } : {}), ...(city ? { recruit_city_slug: city } : {}) };
}

export function clearRedeemedRef() {
  try { localStorage.removeItem("lumo_ref_code"); localStorage.removeItem("lumo_ref_code_ts"); } catch { /* noop */ }
}

export default function RefCapture() {
  const { search } = useLocation();

  useEffect(() => {
    captureUtm(search);
    let ref;
    try {
      const params = new URLSearchParams(search || "");
      ref = params.get("ref");
    } catch { /* ignore malformed query strings */ }
    if (!ref) {
      // Also honor `?referrer=` and `?r=` — same effect. Keeps share
      // links tolerant to whichever query key partners like to use.
      try {
        const params = new URLSearchParams(search || "");
        ref = params.get("referrer") || params.get("r");
      } catch { /* noop */ }
    }
    if (!ref) {
      // Expire any stale ref older than the TTL.
      try {
        const ts = parseInt(localStorage.getItem(REF_TS_KEY) || "0", 10);
        if (ts && Date.now() - ts > REF_TTL_MS) {
          localStorage.removeItem(REF_KEY);
          localStorage.removeItem(REF_TS_KEY);
        }
      } catch { /* noop */ }
      return;
    }
    ref = String(ref).trim().toUpperCase().slice(0, 32);
    if (!ref) return;
    try {
      // First-touch: don't overwrite an already-stored ref (see note above).
      if (!localStorage.getItem(REF_KEY)) {
        localStorage.setItem(REF_KEY, ref);
        localStorage.setItem(REF_TS_KEY, String(Date.now()));
      }
    } catch { /* private mode / storage disabled */ }
  }, [search]);

  return null;
}
